window.__texto({"id": "687837536", "paragrafos": [{"c": "identifica", "t": "PORTARIA SDA/MAPA Nº 1.560, DE 19 DE FEVEREIRO DE 2026"}, {"c": "ementa", "t": "Submete à Consulta Pública a proposta de portaria voltada a estabelecer o regulamento da inspeção industrial e sanitária da carne de aves e seus derivados."}, {"c": "dou-paragraph", "t": "O SECRETÁRIO DE DEFESA AGROPECUÁRIA SUBSTITUTO, DO MINISTÉRIO DA AGRICULTURA E PECUÁRIA, no uso das atribuições que lhe conferem o art. 23 e o art. 48 do Anexo I do Decreto nº 12.642, de 1º de outubro de 2025, tendo em vista o disposto na Lei nº 1.283, de 18 de dezembro de 1950, na Lei nº 7.889, de 23 de novembro de 1989, no Decreto nº 9.013, de 29 de março de 2017, e o que consta do Processo 21000.058928/2024-39, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica submetida à consulta pública, pelo prazo de quarenta e cinco dias, o anexo desta portaria, contendo a proposta de portaria voltada a estabelecer o regulamento da inspeção industrial e sanitária da carne de aves e seus derivados."}, {"c": "dou-paragraph", "t": "Parágrafo único. O projeto de portaria encontra-se disponível na página eletrônica do Ministério da Agricultura e Pecuária, https://www.gov.br/agricultura/pt-br, na seção de consultas públicas."}, {"c": "dou-paragraph", "t": "Art. 2º As sugestões tecnicamente fundamentadas deverão ser encaminhadas por meio do Sistema de Monitoramento de Atos Normativos - SISMAN, da Secretaria de Defesa Agropecuária, por acesso eletrônico: http://sistemasweb.agricultura.gov.br/pages/SISMAN.html."}, {"c": "dou-paragraph", "t": "Parágrafo único. Para acesso ao Sistema de Monitoramento de Atos Normativos - SISMAN, o usuário deverá efetuar cadastro prévio no Sistema de Solicitação de Acesso - SOLICITA, pelo portal eletrônico: https://sistemasweb.agricultura.gov.br/solicita/."}, {"c": "dou-paragraph", "t": "Art. 3º Findo o prazo estabelecido no caput do art. 1º desta portaria, o Departamento de Inspeção de Produtos de Origem Animal avaliará as sugestões recebidas e procederá às adequações pertinentes para posterior publicação da portaria no Diário Oficial da União."}, {"c": "dou-paragraph", "t": "Art. 4º Esta portaria entra em vigor na data de sua publicação."}, {"c": "assina", "t": "ALLAN ROGÉRIO DE ALVARENGA"}, {"c": "dou-paragraph", "t": "ANEXO"}, {"c": "dou-paragraph", "t": "PORTARIA SDA/MAPA Nº , DE DE DE"}, {"c": "dou-paragraph", "t": "Estabelece o regulamento da inspeção industrial e sanitária da carne de aves e seus derivados."}, {"c": "dou-paragraph", "t": "O SECRETÁRIO DE DEFESA AGROPECUÁRIA, DO MINISTÉRIO DA AGRICULTURA E PECUÁRIA, no uso das atribuições que lhe conferem o art. 23 e o art. 48 do Anexo I do Decreto nº 12.642, de 1º de outubro de 2025, tendo em vista o disposto na Lei nº 1.283, de 18 de dezembro de 1950, na Lei nº 7.889, de 23 de novembro de 1989, no Decreto nº 9.013, de 29 de março de 2017, e o que consta do Processo nº 21000.058928/2024-39, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica estabelecido o regulamento da inspeção industrial e sanitária de carne de aves, que dispõe sobre os requisitos das instalações e equipamentos, as condições de higiene, os procedimentos operacionais do abate e processamento, a inspeção ante mortem e a inspeção post mortem para o funcionamento dos estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal, da Secretaria de Defesa Agropecuária, do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES PRELIMINARES"}, {"c": "dou-paragraph", "t": "Art. 2º As aves domésticas de criação compreendem:"}, {"c": "dou-paragraph", "t": "I - frangos, galetos, galinhas e galos;"}, {"c": "dou-paragraph", "t": "II - perus;"}, {"c": "dou-paragraph", "t": "III - patos, marrecos e gansos;"}, {"c": "dou-paragraph", "t": "IV - perdizes, codornas e chucares;"}, {"c": "dou-paragraph", "t": "V - galinhas d'angola ou guiné;"}, {"c": "dou-paragraph", "t": "VI - faisões; e"}, {"c": "dou-paragraph", "t": "VII - pombos."}, {"c": "dou-paragraph", "t": "Art. 3º Podem ser adotadas tecnologias emergentes, métodos inovadores e sistemas automáticos, desde que:"}, {"c": "dou-paragraph", "t": "I - sejam validados pelo estabelecimento, com base em avaliação de risco;"}, {"c": "dou-paragraph", "t": "II - apresentem desempenho equivalente ou superior ao método tradicional; e"}, {"c": "dou-paragraph", "t": "III - sejam previamente autorizados pelo Departamento de Inspeção de Produtos de Origem Animal, quando aplicável, conforme normas específicas."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "DAS INSTALAÇÕES E EQUIPAMENTOS"}, {"c": "dou-paragraph", "t": "Art. 4º As instalações e equipamentos compreendem as dependências mínimas, os equipamentos e utensílios diversos, devendo ser projetados para permitir fluxos contínuos e unidirecionais, proporcionais à capacidade de abate e produção autorizada e atendendo às exigências estabelecidas em normas específicas."}, {"c": "dou-paragraph", "t": "Parágrafo único. As instalações e equipamentos devem ser projetados e instalados para permitir a perfeita execução das atividades e operações, além de dispor das estruturas e utensílios considerados necessários para a realização das atividades."}, {"c": "dou-paragraph", "t": "Art. 5º Para a realização das operações de abate e de processamento de aves, o estabelecimento deve possuir instalações, equipamentos e condições operacionais que garantam a manutenção higiênico-sanitária das matérias-primas e dos produtos em todas as etapas do processo produtivo."}, {"c": "dou-paragraph", "t": "Parágrafo único. As instalações e os equipamentos de que trata o caput devem ser projetados, construídos e mantidos garantindo:"}, {"c": "dou-paragraph", "t": "I - o bem-estar das aves;"}, {"c": "dou-paragraph", "t": "II - a execução adequada e contínua das inspeções ante mortem e post mortem;"}, {"c": "dou-paragraph", "t": "III - a implementação e a efetividade dos programas de autocontrole; e"}, {"c": "dou-paragraph", "t": "IV - a segurança e a qualidade dos produtos."}, {"c": "dou-paragraph", "t": "Art. 6º Nas áreas industriais, equipamentos e utensílios devem:"}, {"c": "dou-paragraph", "t": "I - ser construídos com materiais impermeáveis, laváveis, resistentes à corrosão e de fácil higienização;"}, {"c": "dou-paragraph", "t": "II - permitir acesso para verificação, manutenção e higienização; e"}, {"c": "dou-paragraph", "t": "III - ser prevenidos de acúmulo de resíduos, umidade e formação de condensação."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os equipamentos devem conter dispositivos para regulagem conforme a espécie, categoria e tamanho das aves."}, {"c": "dou-paragraph", "t": "Art. 7º As pias para higienização de mãos devem atender ao seguinte:"}, {"c": "dou-paragraph", "t": "I - ser instaladas nas barreiras sanitárias, nos vestiários e sanitários, nas salas de manipulação de alimentos e onde se fizerem necessárias;"}, {"c": "dou-paragraph", "t": "II - ser estrategicamente localizadas para facilitar o seu uso pelos funcionários;"}, {"c": "dou-paragraph", "t": "III - possuir torneiras acionadas a pedal ou por outros meios que impeçam o uso direto das mãos; e"}, {"c": "dou-paragraph", "t": "IV - possuir recipiente para sabão líquido e toalhas descartáveis ou outro dispositivo para secagem das mãos."}, {"c": "dou-paragraph", "t": "Art. 8º Os acessos aos setores industriais devem possuir barreira sanitária, em local coberto, dispostas e dimensionadas para atender a demanda e o fluxo dos funcionários de cada setor."}, {"c": "dou-paragraph", "t": "§ 1º É facultada a instalação de barreira sanitária junto aos anexos da área produtiva, desde que mantidas as condições higiênico-sanitárias."}, {"c": "dou-paragraph", "t": "§ 2º A barreira sanitária deve apresentar:"}, {"c": "dou-paragraph", "t": "I - lavador de botas;"}, {"c": "dou-paragraph", "t": "II - pias dotadas de torneiras com fechamento não manual;"}, {"c": "dou-paragraph", "t": "III - método higiênico para secagem das mãos;"}, {"c": "dou-paragraph", "t": "IV - sabão líquido;"}, {"c": "dou-paragraph", "t": "V - sanitizante;"}, {"c": "dou-paragraph", "t": "VI - lixeiras com acionamento não manual da tampa;"}, {"c": "dou-paragraph", "t": "VII - quando houver acesso direto ao meio externo, cortina de ar ou equipamento similar para evitar o acesso de pragas, desde que autorizado pelo Departamento de Inspeção de Produtos de Origem Animal; e"}, {"c": "dou-paragraph", "t": "VIII - iluminação suficiente para visualização e execução das operações."}, {"c": "dou-paragraph", "t": "Art. 9º As barreiras sanitárias devem ser fechadas em gabinete nos setores de abate (sangria, escaldagem e depenagem, e evisceração), cortes e desossa, e industrialização de produtos cárneos."}, {"c": "dou-paragraph", "t": "Parágrafo único. É proibido o acesso direto aos setores de que trata o caput com a área externa, exceto para as saídas de emergência."}, {"c": "dou-paragraph", "t": "Art. 10. Todos os setores do estabelecimento devem apresentar iluminação artificial adequada às operações realizadas, devendo:"}, {"c": "dou-paragraph", "t": "I - ser posicionada garantindo iluminação homogênea e suficiente para a correta execução das atividades;"}, {"c": "dou-paragraph", "t": "II - não empregar luzes ou filtros que alterem ou dificultem a correta percepção da coloração de carcaças, vísceras e demais produtos; e"}, {"c": "dou-paragraph", "t": "III - atender a um nível mínimo de intensidade luminosa de quinhentos e quarenta lux na sala de necropsia, no Departamento de Inspeção Final, nos pontos críticos de controle de avaliação visual, na pré-inspeção, nas linhas de inspeção e nos locais de revisão ou reinspeção de produtos comestíveis."}, {"c": "dou-paragraph", "t": "Parágrafo único. As lâmpadas que apresentem risco de estilhaçamento devem estar protegidas por dispositivos de segurança."}, {"c": "dou-paragraph", "t": "Art. 11. O forro da área industrial deve ser de material resistente, de superfície lisa e higienizável."}, {"c": "dou-paragraph", "t": "Parágrafo único. O forro é dispensado nos galpões de espera, na plataforma de recepção de aves vivas, pendura, insensibilização e sangria, escaldagem e depenagem, desde que a cobertura seja construída de material impermeável, resistente, de fácil higienização, que proporcione uma perfeita vedação à entrada de pragas e evite o desprendimento de partículas."}, {"c": "dou-paragraph", "t": "Art. 12. Os ambientes nos quais há risco imediato de contaminação de utensílios e equipamentos, devem possuir dispositivos de sanitização com água renovável à temperatura mínima de 82,2 °C (oitenta e dois vírgula dois graus Celsius)."}, {"c": "dou-paragraph", "t": "Art. 13. Os equipamentos utilizados na condução de produtos comestíveis, tais como, por exemplo, esteiras, calhas, tubulações, carrinhos ou caixas, devem propiciar fluxo contínuo e unidirecional, permitir a higienização completa e prevenir a contaminação cruzada."}, {"c": "dou-paragraph", "t": "Parágrafo único. Quando a condução de produtos comestíveis ocorrer por meio de tubulações ou chutes fechados, estes devem permitir o monitoramento e a verificação da sua condição higiênica, ser desmontáveis, bem como possibilitar a completa higienização em toda a sua extensão."}, {"c": "dou-paragraph", "t": "Art. 14. A condução das águas servidas e dos resíduos do processo deve ocorrer via tubulações ou sistemas específicos, em fluxo contínuo, que permitam a fácil higienização, com dispositivos e equipamentos destinados a prevenir a contaminação cruzada e o acesso de pragas às áreas industriais."}, {"c": "dou-paragraph", "t": "Art. 15. Os estabelecimentos devem disponibilizar equipamento ou dispositivo que permita a correta identificação do lote em abate e sua correlação desde a inspeção ante mortem, pré-inspeção, linhas de inspeção post mortem e Departamento de Inspeção Final, com sinalização inequívoca da troca de lotes."}, {"c": "dou-paragraph", "t": "Parágrafo único. As áreas de inspeção, ou próximo a elas, devem possuir dispositivo que permita a interrupção imediata do processo de abate, quando aplicável."}, {"c": "dou-paragraph", "t": "Art. 16. Os estabelecimentos devem possuir dispositivos, de fácil acesso ao Serviço de Inspeção Federal, para verificação da velocidade da nórea, por meio de painéis indicativos."}, {"c": "dou-paragraph", "t": "Art. 17. As nóreas de todos os setores devem possuir sistema para lavagem dos seus ganchos."}, {"c": "dou-paragraph", "t": "Art. 18. Deve haver separação física entre as áreas de embalagem primária e embalagem secundária para todos os setores do estabelecimento."}, {"c": "dou-paragraph", "t": "Parágrafo único. Quando a embalagem primária e a embalagem secundária forem realizadas de forma simultânea e contínua no mesmo fluxo de produção, devem ser garantidas condições higiênico-sanitárias adequadas, prevenindo a contaminação dos produtos."}, {"c": "dou-paragraph", "t": "Art. 19. Os contentores de acondicionamento de produtos comestíveis devem ser de cor clara, para facilitar a avaliação de sua higiene e integridade."}, {"c": "dou-paragraph", "t": "Parágrafo único. É proibido o depósito de caixas e outros contentores diretamente no piso, devendo ser mantidos em suportes de altura suficiente para prevenir a contaminação por contato com o piso."}, {"c": "dou-paragraph", "t": "Art. 20. Devem haver estruturas ou locais para depositar utensílios e equipamentos de uso individual, tais como, por exemplo, chairas, facas, luvas e demais instrumentos, tanto durante as operações como durante os seus intervalos, prevenindo a contaminação cruzada e o contato direto com superfícies de trabalho, carcaças e produtos."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Recepção de aves vivas"}, {"c": "dou-paragraph", "t": "Art. 21. O setor de recepção de aves vivas contempla os galpões de espera, a plataforma de recepção de aves vivas, a área de inspeção ante mortem, a sala de necropsia, a área de pendura e a área de lavagem e armazenamento de caixas de transporte de aves vivas."}, {"c": "dou-paragraph", "t": "Art. 22. Os galpões de espera devem ser instalados em local específico, a uma distância que não comprometa as condições higiênicas das áreas de produção, com cobertura contra intempéries e ventilação e, conforme o caso, umidificação ambiente controlada, garantindo o conforto térmico das aves e atendendo as normas de bem-estar animal."}, {"c": "dou-paragraph", "t": "Art. 23. A área de recepção deve atender ao seguinte:"}, {"c": "dou-paragraph", "t": "I - estar instalada em local coberto, protegida dos ventos predominantes e de incidência direta dos raios solares, atendendo as condições climáticas regionais, sem prejuízo para a ventilação e a iluminação;"}, {"c": "dou-paragraph", "t": "II - apresentar estruturas e equipamentos para o desembarque e o recebimento das aves, que minimizem dor, sofrimento ou desconforto às aves, visando atender às normas de bem-estar animal;"}, {"c": "dou-paragraph", "t": "III - possuir dispositivos que permitam a movimentação dos contentores e estrados, os quais, após vazios, devem ser encaminhados para o setor próprio de limpeza, higienização e desinfecção; e"}, {"c": "dou-paragraph", "t": "IV - possuir recipientes ou contentores, identificados, para descarte das aves que chegarem mortas na área de pendura."}, {"c": "dou-paragraph", "t": "Art. 24. A sala de necropsia deve:"}, {"c": "dou-paragraph", "t": "I - estar identificada e localizada nas adjacências das áreas de recepção e inspeção ante mortem, sem interferir no fluxo de produção do estabelecimento; e"}, {"c": "dou-paragraph", "t": "II - ser equipada com armário, mesa de necropsia, pia, sabão líquido, sanitizante, dispositivo para secagem de mãos, dispositivo de sanitização de utensílios e recipiente que possibilite a remoção contínua dos resíduos."}, {"c": "dou-paragraph", "t": "Art. 25. A área de inspeção ante mortem deve apresentar o seguinte:"}, {"c": "dou-paragraph", "t": "I - local identificado, de fácil acesso, com barreira sanitária disponível;"}, {"c": "dou-paragraph", "t": "II - estrutura e equipamentos que possibilitem o descarregamento das caixas com aves vivas;"}, {"c": "dou-paragraph", "t": "III - local para permanência das caixas com aves vivas até a realização do exame clínico;"}, {"c": "dou-paragraph", "t": "IV - iluminação mínima de quinhentos e quarenta lux;"}, {"c": "dou-paragraph", "t": "V - local para avaliação clínica das aves em estação e em movimento;"}, {"c": "dou-paragraph", "t": "VI - local para manipulação das aves durante a avaliação clínica;"}, {"c": "dou-paragraph", "t": "VII - pias dotadas de torneiras com fechamento não manual, sabão líquido, sanitizante e dispositivo para secagem de mãos;;"}, {"c": "dou-paragraph", "t": "VIII - pontos de água para higienização das instalações; e"}, {"c": "dou-paragraph", "t": "IX - local para guarda de equipamentos de proteção individual e manuseio de documentos."}, {"c": "dou-paragraph", "t": "Art. 26. A área de lavagem e armazenamento de caixas de transporte de aves vivas deve apresentar dispositivo de limpeza, higienização e desinfecção, bem como área de armazenamento de caixas limpas e higienizadas."}, {"c": "dou-paragraph", "t": "Parágrafo único. Caixas e estrados sujos não podem ser depositados no mesmo local das caixas e estrados já limpos e higienizados."}, {"c": "dou-paragraph", "t": "Art. 27. O setor de recepção de aves vivas deve possuir um local específico, afastado da plataforma de recepção, para a higienização de veículos transportadores de aves vivas, dispondo de drenagem e destinação dos efluentes."}, {"c": "dou-paragraph", "t": "§ 1º É proibida a higienização de veículos transportadores de aves vivas nas áreas de desembarque e de espera."}, {"c": "dou-paragraph", "t": "§ 2º É proibido o carregamento de caixas de aves vivas em caminhões que não se apresentarem em condições higiênico-sanitárias adequadas."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Insensibilização e Sangria"}, {"c": "dou-paragraph", "t": "Art. 28. As instalações para insensibilização e sangria devem estar separadas fisicamente, através de paredes inteiras, das demais áreas operacionais e devem atender, no mínimo, aos seguintes critérios:"}, {"c": "dou-paragraph", "t": "I - equipamentos para insensibilização e sangria adaptados ou específicos para a espécie ou categoria de ave abatida, conforme normas específicas;"}, {"c": "dou-paragraph", "t": "II - ponto de água, com acionamento não manual, nas estações de trabalho;"}, {"c": "dou-paragraph", "t": "III - calhas ou outros meios que propiciem o recolhimento do sangue de forma adequada e contínua, conforme a finalidade ou destinação pretendida; e"}, {"c": "dou-paragraph", "t": "IV - equipamento para higienização de mãos e dispositivos para sanitização de utensílios próximos às operações."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Escaldagem e Depenagem"}, {"c": "dou-paragraph", "t": "Art. 29. As instalações destinadas para escaldagem e depenagem devem ser fisicamente isoladas das demais áreas operacionais por paredes completas e contínuas."}, {"c": "dou-paragraph", "t": "§1º As aves podem ser escaldadas pelos seguintes processos:"}, {"c": "dou-paragraph", "t": "I - pulverização de água quente e vapor;"}, {"c": "dou-paragraph", "t": "II - imersão em tanque com água aquecida; ou"}, {"c": "dou-paragraph", "t": "III - outro método autorizado pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§2º O setor de escaldagem e depenagem deve atender, no mínimo, ao seguinte:"}, {"c": "dou-paragraph", "t": "I - possuir equipamentos para ventilação e exaustão dos vapores e partículas em suspensão gerados no setor;"}, {"c": "dou-paragraph", "t": "II - equipamentos para escaldagem e depenagem devem ser adaptados ou específicos para a espécie ou categoria de ave abatida;"}, {"c": "dou-paragraph", "t": "III - as depenadeiras devem possuir sistema de remoção e transporte contínuo de resíduos; e"}, {"c": "dou-paragraph", "t": "IV - possuir equipamentos próprios em área destinada à escaldagem de pés e cabeças e à remoção da cutícula dos pés, quando se destinarem a fins comestíveis."}, {"c": "dou-paragraph", "t": "Art. 30. Deve haver um ponto de pré-inspeção para avaliação de todas as carcaças ou partes de carcaças destinadas a fins comestíveis, o qual deve apresentar o seguinte:"}, {"c": "dou-paragraph", "t": "I - local identificado, de fácil acesso;"}, {"c": "dou-paragraph", "t": "II - estação de trabalho onde os auxiliares de inspeção possam realizar o completo exame das carcaças;"}, {"c": "dou-paragraph", "t": "III - iluminação mínima na altura da carcaça de quinhentos e quarenta lux;"}, {"c": "dou-paragraph", "t": "IV - sistema para registros das lesões;"}, {"c": "dou-paragraph", "t": "V - ponto de água, com acionamento não manual, nas estações de trabalho; e"}, {"c": "dou-paragraph", "t": "VI - sistema de coleta contínua de resíduos e partes condenadas."}, {"c": "dou-paragraph", "t": "Parágrafo único. O ponto de pré-inspeção pode ser localizado neste ou em outro setor, desde que seja anterior à remoção de qualquer parte da carcaça."}, {"c": "dou-paragraph", "t": "Art. 31. Um sistema para lavagem das carcaças deve ser instalado na transição entre os setores de escaldagem e depenagem com o setor de evisceração, sendo facultada sua localização em qualquer um desses setores."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os sistemas de lavagem devem ser dotados de água sob adequada pressão, com jatos orientados de forma que toda a carcaça seja lavada, inclusive os pés."}, {"c": "dou-paragraph", "t": "Seção IV"}, {"c": "dou-paragraph", "t": "Evisceração"}, {"c": "dou-paragraph", "t": "Art. 32. As instalações do setor de evisceração devem estar separadas fisicamente, através de paredes inteiras, das demais áreas operacionais e devem atender, no mínimo, ao seguinte:"}, {"c": "dou-paragraph", "t": "I - apresentar equipamentos e utensílios específicos e regulados para realizar os procedimentos de eventração e evisceração de forma eficiente, higiênica e prevenindo contaminação cruzada;"}, {"c": "dou-paragraph", "t": "II - os equipamentos e utensílios devem possuir dispositivos, automáticos ou não, para higienização contínua;"}, {"c": "dou-paragraph", "t": "III - a nórea deve:"}, {"c": "dou-paragraph", "t": "a) ser projetada e construída de modo que garanta o distanciamento adequado das carcaças com as paredes, calhas e outras estruturas e superfícies de contato; e"}, {"c": "dou-paragraph", "t": "b) manter a posição adequada da carcaça para os trabalhos de manipulação e inspeção."}, {"c": "dou-paragraph", "t": "IV - apresentar equipamentos para higienização de mãos e dispositivos para sanitização de utensílios em número suficiente e próximos às operações;"}, {"c": "dou-paragraph", "t": "V - apresentar pontos de água, com acionamento não manual, nas posições de trabalho;"}, {"c": "dou-paragraph", "t": "VI - apresentar calha de evisceração para as operações de abate, bem como para coleta e remoção de resíduos e material considerado não comestível, de forma contínua e unidirecional, a qual deve apresentar:"}, {"c": "dou-paragraph", "t": "a) no mínimo, um metro de espaçamento entre um e outro funcionário, garantindo a adequada execução das operações; e"}, {"c": "dou-paragraph", "t": "b) pontos de água para higienização das mãos, instalados em suas bordas, na proporção mínima de um ponto de água para cada dois funcionários, sem prejuízo das demais exigências estabelecidas em norma específica."}, {"c": "dou-paragraph", "t": "VII - apresentar sistema de lavagem final das superfícies interna e externa das carcaças, imediatamente anterior ao sistema de pré-resfriamento, com parâmetros estabelecidos e validados em programa de autocontrole, sendo proibida a entrada de carcaças com contaminação visível no sistema de pré-resfriamento."}, {"c": "dou-paragraph", "t": "Art. 33. O espaçamento entre os ganchos deve garantir o distanciamento entre as carcaças para prevenir contaminação cruzada."}, {"c": "dou-paragraph", "t": "Art. 34. As linhas de inspeção post mortem devem apresentar o seguinte:"}, {"c": "dou-paragraph", "t": "I - local identificado, de fácil acesso;"}, {"c": "dou-paragraph", "t": "II - estação de trabalho onde os auxiliares de inspeção possam realizar o completo exame das carcaças e suas vísceras;"}, {"c": "dou-paragraph", "t": "III - manter espaçamento mínimo de um metro entre cada auxiliar de inspeção;"}, {"c": "dou-paragraph", "t": "IV - iluminação mínima na altura da carcaça de quinhentos e quarenta lux;"}, {"c": "dou-paragraph", "t": "V - ponto de água, com acionamento não manual, em todas as posições de trabalho; e"}, {"c": "dou-paragraph", "t": "VI - sistema de coleta contínua de resíduos e partes condenadas."}, {"c": "dou-paragraph", "t": "Parágrafo único. No caso de condenação de partes de carcaças nas linhas de inspeção, deve haver um sistema para o registro das lesões, bem como dispositivos para sanitização de utensílios próximos às operações."}, {"c": "dou-paragraph", "t": "Art. 35. O Departamento de Inspeção Final deve apresentar o seguinte:"}, {"c": "dou-paragraph", "t": "I - local identificado, de fácil acesso;"}, {"c": "dou-paragraph", "t": "II - estação de trabalho, com espaçamento mínimo de um metro, onde os auxiliares de inspeção possam realizar o completo exame das carcaças e suas vísceras;"}, {"c": "dou-paragraph", "t": "III - iluminação mínima na altura da carcaça de quinhentos e quarenta lux;"}, {"c": "dou-paragraph", "t": "IV - sistema para registros das lesões, em posição que permita fácil acesso aos auxiliares de inspeção;"}, {"c": "dou-paragraph", "t": "V - ponto de água com acionamento não manual;"}, {"c": "dou-paragraph", "t": "VI - sistema de coleta contínua de resíduos e partes condenadas;"}, {"c": "dou-paragraph", "t": "VII - sistema para lavagem dos ganchos da nórea do Departamento de Inspeção Final; e"}, {"c": "dou-paragraph", "t": "VIII - dispositivos para sanitização de utensílios, próximos às operações."}, {"c": "dou-paragraph", "t": "Seção V"}, {"c": "dou-paragraph", "t": "Pré-resfriamento"}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Pré-resfriamento de carcaças"}, {"c": "dou-paragraph", "t": "Art. 36. As instalações do setor de pré-resfriamento de carcaças devem estar separadas fisicamente, através de paredes inteiras, das demais áreas operacionais."}, {"c": "dou-paragraph", "t": "Art. 37. O setor deve apresentar ventilação adequada para prevenir a condensação, bem como possuir um sistema eficiente de coleta de águas residuais."}, {"c": "dou-paragraph", "t": "Art. 38. O pré-resfriamento das carcaças pode ser realizado através dos seguintes métodos:"}, {"c": "dou-paragraph", "t": "I - aspersão de água gelada;"}, {"c": "dou-paragraph", "t": "II - imersão em água por resfriadores contínuos;"}, {"c": "dou-paragraph", "t": "III - resfriamento por ar em câmaras frigoríficas; ou"}, {"c": "dou-paragraph", "t": "IV - outro método autorizado pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 1º O pré-resfriamento de carcaças pode ser realizado em várias etapas, contemplando mais de um tanque de água gelada ou até combinando diferentes métodos."}, {"c": "dou-paragraph", "t": "§ 2º A entrada de água gelada nos tanques de resfriamento deve estar localizada na extremidade oposta à entrada de carcaças."}, {"c": "dou-paragraph", "t": "§ 3º É permitida a utilização de injeção de ar (borbulhamento) nos tanques de pré-resfriamento por imersão, desde que este ar seja previamente filtrado."}, {"c": "dou-paragraph", "t": "Art. 39. Os sistemas de pré-resfriamento de carcaças devem apresentar equipamentos de mensuração que permitam o controle e registro contínuo da temperatura da água ou ar e da vazão de água, no caso de pré-resfriadores por imersão."}, {"c": "dou-paragraph", "t": "Art. 40. O gotejamento pode ser realizado através dos seguintes métodos:"}, {"c": "dou-paragraph", "t": "I - suspensão das carcaças em trilhagem aérea, com calha coletora de água;"}, {"c": "dou-paragraph", "t": "II - peneira rotativa para a remoção da água excedente de carcaças; ou"}, {"c": "dou-paragraph", "t": "III - outro método autorizado pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Pré-resfriamento de miúdos, partes e cortes"}, {"c": "dou-paragraph", "t": "Art. 41. Os miúdos (moela, coração e fígado), cortes, partes de carcaças, gordura cavitária e outros produtos comestíveis devem ser processados em setor próprio com fluxo adequado."}, {"c": "dou-paragraph", "t": "Art. 42. O setor deve apresentar ventilação adequada para prevenir a condensação, bem como possuir um sistema eficiente de coleta de águas residuais."}, {"c": "dou-paragraph", "t": "Art. 43. O pré-resfriamento dos miúdos, cortes, partes de carcaças, gordura cavitária e outros produtos comestíveis, pode ser realizado através de imersão em água por resfriadores contínuos."}, {"c": "dou-paragraph", "t": "Art. 44. Os sistemas de pré-resfriamento de miúdos, cortes, partes de carcaças, gordura cavitária e outros produtos comestíveis devem apresentar equipamentos de mensuração que permitam o controle e registro contínuo da temperatura da água e da vazão de água, no caso de pré-resfriadores por imersão."}, {"c": "dou-paragraph", "t": "Seção VI"}, {"c": "dou-paragraph", "t": "Cortes e desossa, classificação e embalagem"}, {"c": "dou-paragraph", "t": "Art. 45. O estabelecimento deve possuir instalações próprias para cortes, desossa, classificação e embalagem de carcaças, separadas fisicamente, através de paredes inteiras, das demais áreas operacionais, bem como dispondo de lavatórios de mãos distribuídos pela área."}, {"c": "dou-paragraph", "t": "§ 1º Quando as carcaças inteiras forem direcionadas diretamente para embalagem primária, as etapas de classificação e embalagem primária podem ser realizadas em área contígua ao setor de pré-resfriamento."}, {"c": "dou-paragraph", "t": "§ 2º As áreas destinadas ao corte, desossa, classificação e embalagem de carcaças devem ser dotadas de equipamentos de medição que possibilitem o controle e o registro de forma contínua, de forma visível e auditável, da temperatura do ambiente, que não deve ultrapassar 12,0 °C (doze graus Celsius)."}, {"c": "dou-paragraph", "t": "Art. 46. Os estabelecimentos que produzem carne temperada de ave devem possuir dependências exclusivas para a armazenagem dos condimentos e preparo de tempero."}, {"c": "dou-paragraph", "t": "Parágrafo único. É permitida a produção de carne temperada junto ao setor de cortes e desossa, desde que não interfira no fluxo de produção, nas condições higiênico-sanitárias do setor e prevenindo a contaminação cruzada."}, {"c": "dou-paragraph", "t": "Art. 47. A produção de carne mecanicamente separada deve ocorrer em setor próprio, atendendo norma específica."}, {"c": "dou-paragraph", "t": "Art. 48. Setores de industrialização de produtos cárneos frescais, cozidos, defumados, curados, esterilizados e outros devem atender normas específicas."}, {"c": "dou-paragraph", "t": "Seção VII"}, {"c": "dou-paragraph", "t": "Frigorificação"}, {"c": "dou-paragraph", "t": "Art. 49. O setor de frigorificação contempla as câmaras de resfriamento, congelamento, descongelamento e estocagem, assim como os túneis de congelamento, antecâmaras e demais câmaras frigoríficas."}, {"c": "dou-paragraph", "t": "Art. 50. O setor de frigorificação deve apresentar equipamentos geradores de frio, garantindo a manutenção das temperaturas estabelecidas na legislação e nos programas de autocontrole."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os equipamentos geradores de frio devem possuir dispositivos de medição que permitam o controle e o registro da temperatura, de forma contínua, visível e auditável."}, {"c": "dou-paragraph", "t": "Art. 51. As portas das câmaras devem apresentar vedação adequada, bem como de dispositivos que previnam a troca de calor entre ambientes e a formação de condensação, neve ou gelo."}, {"c": "dou-paragraph", "t": "Art. 52. É proibido haver ralos no interior das câmaras."}, {"c": "dou-paragraph", "t": "Seção VIII"}, {"c": "dou-paragraph", "t": "Expedição"}, {"c": "dou-paragraph", "t": "Art. 53. O setor de expedição é destinado à circulação dos produtos das câmaras frigoríficas para o veículo transportador, podendo ser dispensado quando a localização da antecâmara permitir o acesso direto ao transporte."}, {"c": "dou-paragraph", "t": "Art. 54. O setor de expedição deve atender aos seguintes critérios:"}, {"c": "dou-paragraph", "t": "I - apresentar uma área dimensionada unicamente para pesagem, quando for o caso, e acesso ao transporte, proibido o acúmulo de produtos;"}, {"c": "dou-paragraph", "t": "II - ser separado fisicamente do meio externo através de paredes inteiras, dispondo de aberturas, tais como, por exemplo, portas ou óculos, somente nos pontos de acoplamento dos veículos transportadores;"}, {"c": "dou-paragraph", "t": "III - as aberturas para o meio externo devem apresentar mecanismos que impeçam a entrada de pragas, ar externo e sujidades; e"}, {"c": "dou-paragraph", "t": "IV - as docas devem possuir cobertura externa com, no mínimo, três metros (3m) para proteção contra intempéries, bem como dispositivos para o perfeito acoplamento dos veículos transportadores."}, {"c": "dou-paragraph", "t": "Seção IX"}, {"c": "dou-paragraph", "t": "Outras instalações e equipamentos"}, {"c": "dou-paragraph", "t": "Art. 55. A higienização de recipientes e utensílios, incluindo facas, chairas, bandejas, caixas, carros de transporte, luvas de malha de aço e outros, deve ser realizada em sala específica, equipada e com fluxo de produção adequado, separada fisicamente, através de paredes inteiras, das áreas de produção."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os recipientes e utensílios já higienizados, devem ser depositados em local próprio e separado do local de recepção e higienização desses utensílios."}, {"c": "dou-paragraph", "t": "Art. 56. As instalações devem apresentar dependência própria e exclusiva para depósito e armazenamento do material de embalagem primária."}, {"c": "dou-paragraph", "t": "Art. 57. As instalações devem apresentar local próprio e separado para depósito e montagem de embalagem secundária, tal como, por exemplo, caixas de papelão, apresentando um fluxo adequado para o abastecimento da produção."}, {"c": "dou-paragraph", "t": "Art. 58. As instalações devem apresentar dependências exclusivas para depósito e armazenamento de ingredientes e matérias-primas."}, {"c": "dou-paragraph", "t": "Art. 59. As instalações devem apresentar dependência exclusiva para armazenamento de gelo, seja ele produzido no próprio estabelecimento ou adquirido de terceiros."}, {"c": "dou-paragraph", "t": "Art. 60. Quando a lavagem de veículos transportadores de produtos for realizada no estabelecimento, as suas instalações devem ser independentes e afastadas das destinadas à higienização dos veículos transportadores de aves vivas."}, {"c": "dou-paragraph", "t": "Art. 61. As dependências sociais, tais como, por exemplo, vestiários, sanitários e refeitórios, devem estar separadas das áreas de produção, bem como atender aos seguintes requisitos:"}, {"c": "dou-paragraph", "t": "I - devem ser construídas conforme o disposto em norma específica;"}, {"c": "dou-paragraph", "t": "II - os vestiários devem ser equipados com dispositivos para guarda individual de pertences, possuir fluxo de pessoal adequado e separação entre a roupa civil e o uniforme;"}, {"c": "dou-paragraph", "t": "III - os vestiários devem ser isolados das instalações sanitárias, tais como, por exemplo, sanitários e chuveiros;"}, {"c": "dou-paragraph", "t": "IV - vestiários e sanitários distintos para os funcionários que manipulam aves vivas e resíduos não comestíveis e para os que manipulam produtos comestíveis, ingredientes e embalagens;"}, {"c": "dou-paragraph", "t": "V - o uso do refeitório é obrigatório pelos funcionários que fazem suas refeições no estabelecimento, sendo proibido que outras dependências ou áreas sejam usadas para tal finalidade; e"}, {"c": "dou-paragraph", "t": "VI - possuir refeitório separado para os funcionários que manipulam aves vivas e produtos não comestíveis."}, {"c": "dou-paragraph", "t": "Art. 62. A sede do Serviço de Inspeção Federal deve apresentar sala de trabalho equipada, sala equipada para guarda de amostras, arquivo, vestiários e sanitários, em número e dimensões suficientes às necessidades dos trabalhos."}, {"c": "dou-paragraph", "t": "Parágrafo único. A sede do Serviço de Inspeção Federal deve ser construída com acesso exclusivo e independente de qualquer outra dependência do estabelecimento."}, {"c": "dou-paragraph", "t": "Art. 63. Outras dependências auxiliares, tais como, por exemplo, escritórios, depósitos, almoxarifados e oficinas, devem ser construídas em áreas que não prejudiquem os trabalhos industriais."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "CONDIÇÕES DE HIGIENE"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Condições gerais"}, {"c": "dou-paragraph", "t": "Art. 64. As instalações, os equipamentos e os sistemas empregados no abate e no processamento devem ser submetidos a procedimentos de higienização pré-operacional e operacional, definidos, monitorados e verificados pelo estabelecimento, garantindo as condições higiênico-sanitárias antes do início das suas atividades e durante todo o seu período de funcionamento."}, {"c": "dou-paragraph", "t": "Art. 65. Durante as operações, devem ser adotados procedimentos de higiene operacional capazes de prevenir a contaminação das carcaças, partes da carcaça e demais produtos, considerando os fluxos de produção, a organização das atividades, o uso adequado de equipamentos e utensílios e a segregação de operações incompatíveis."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Saúde e Higiene de Pessoal"}, {"c": "dou-paragraph", "t": "Art. 66. O estabelecimento deve implementar, conforme programas de autocontrole, procedimentos relativos à saúde e higiene pessoal, contemplando aptidão médica para manipulação de produtos comestíveis, capacitação, monitoramento e verificação das práticas e dos hábitos higiênicos dos funcionários."}, {"c": "dou-paragraph", "t": "Art. 67. Os funcionários que manipulam produtos comestíveis, ingredientes e embalagens devem iniciar a jornada de trabalho utilizando uniforme limpo, em cor branca ou outra cor clara, mantido em condições higiênicas durante as operações."}, {"c": "dou-paragraph", "t": "Art. 68. Os funcionários que manipulam aves vivas ou produtos não comestíveis devem utilizar uniformes de cores distintas daqueles usados pelos manipuladores de produtos comestíveis, ingredientes e embalagens, reduzindo o risco de contaminação cruzada."}, {"c": "dou-paragraph", "t": "Art. 69. Os uniformes devem ser trocados, no mínimo, diariamente, ou sempre que houver comprometimento das condições de higiene, podendo o seu intervalo de troca ser ajustado conforme avaliação de risco sanitário."}, {"c": "dou-paragraph", "t": "Art. 70. Os Equipamentos de Proteção Individual devem ser mantidos em condições higiênicas durante todo o seu uso."}, {"c": "dou-paragraph", "t": "§ 1º Os Equipamentos de Proteção Individual descartáveis, tais como, por exemplo, luvas de manipulação, aventais e outros, devem ser descartados em local específico, após o seu uso."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento deve apresentar local para higienização e guarda de Equipamentos de Proteção Individual reaproveitáveis, nos setores necessários."}, {"c": "dou-paragraph", "t": "Art. 71. Os vestiários, sanitários e lavatórios devem ser mantidos em condições higiênicas, em bom estado de conservação e em condições compatíveis com sua finalidade e capacidade de uso."}, {"c": "dou-paragraph", "t": "Art. 72. O acesso aos setores de produção deve ocorrer por barreiras sanitárias, conforme procedimentos em programas de autocontrole, de forma compatível com o risco das atividades desenvolvidas."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Higiene de utensílios"}, {"c": "dou-paragraph", "t": "Art. 73. Os utensílios utilizados durante as operações devem ser higienizados e sanitizados de forma a prevenir a contaminação dos produtos."}, {"c": "dou-paragraph", "t": "§ 1º Deve haver recinto específico para higienização e sanitização dos utensílios, com fluxo que impeça contaminação cruzada."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento deve possuir procedimentos para o controle e o registro da higienização e da sanitização de utensílios durante as operações nos setores, compatíveis com o seu risco sanitário."}, {"c": "dou-paragraph", "t": "§ 3º Os dispositivos destinados à sanitização de utensílios devem ser adequados ao volume e ao tipo de operação, mantidos em condições de funcionamento e utilizados conforme os procedimentos estabelecidos."}, {"c": "dou-paragraph", "t": "Art. 74. Deve haver controle da distribuição, do uso e da troca de utensílios durante as operações, evitando o seu uso inadequado e a contaminação cruzada."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "PROCEDIMENTOS OPERACIONAIS"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Recebimento de aves"}, {"c": "dou-paragraph", "t": "Art. 75. Sem prejuízo ao atendimento das normas de saúde animal ou outras aplicáveis à recepção de aves vivas, o estabelecimento deve realizar a avaliação pré-abate, no estabelecimento, contemplando todos os lotes recebidos, incluindo:"}, {"c": "dou-paragraph", "t": "I - a análise documental;"}, {"c": "dou-paragraph", "t": "II - a avaliação visual de uma amostra das aves vivas, no mínimo, na primeira carga de cada lote; e"}, {"c": "dou-paragraph", "t": "III - verificação das condições de transporte, descarregamento, alojamento e bem-estar animal."}, {"c": "dou-paragraph", "t": "§1º O estabelecimento é responsável pela confirmação de recebimento de aves em suas instalações, inclusive as solicitadas pelo serviço oficial de saúde animal para fins de controle de trânsito."}, {"c": "dou-paragraph", "t": "§ 2º Quando houver restrição ou determinação expressa pelo serviço oficial de saúde animal, quanto à destinação das aves ou seus produtos, o estabelecimento deve segregar e identificar os lotes de aves inaptos ao abate normal e comunicar estas ações ao Serviço de Inspeção Federal."}, {"c": "dou-paragraph", "t": "Art. 76. Na avaliação documental, deve ser verificada a documentação de trânsito e sanitária das aves quanto as suas informações, validade, veracidade e fidedignidade, conforme normas específicas da Secretaria de Defesa Agropecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. No caso de detecção de ausência da documentação ou divergências entre a documentação e o trânsito efetivado, o estabelecimento deve segregar e identificar os lotes de aves e adotar as providências previstas em determinações do Departamento de Saúde Animal, da Secretaria de Defesa Agropecuária, e do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 77. O estabelecimento deve atender aos períodos de jejum e dieta hídrica conforme norma específica."}, {"c": "dou-paragraph", "t": "Art. 78. A avaliação pré-abate deve ser realizada pelo estabelecimento a fim de identificar a prevalência de alterações no lote, para dimensionar as ações a serem tomadas no processo de abate, considerando a capacidade operacional e o fluxo de abate."}, {"c": "dou-paragraph", "t": "§ 1º A avaliação de que trata o caput é realizada sob responsabilidade e supervisão do médico-veterinário do estabelecimento."}, {"c": "dou-paragraph", "t": "§ 2º Sempre que necessário, o estabelecimento deve adotar medidas para adequação do processo de abate para minimizar o impacto de lotes com alta prevalência de alterações no controle higiênico-sanitário do abate."}, {"c": "dou-paragraph", "t": "§ 3º Quando, ao longo do abate de um lote, forem percebidas mudanças na prevalência de alterações avaliada previamente, deve ser realizada a revisão das medidas adotadas para manutenção da condição higiênico-sanitária adequada do processo e dos produtos."}, {"c": "dou-paragraph", "t": "Art. 79. O estabelecimento deve manter a programação e a ordem de entrada dos lotes de aves atualizados junto ao Serviço de Inspeção Federal durante todo o curso do abate."}, {"c": "dou-paragraph", "t": "Art. 80. Quando não for possível o abate imediato, os veículos transportadores com as aves devem ser mantidos nos galpões de espera, atendida a legislação de bem-estar animal."}, {"c": "dou-paragraph", "t": "§ 1º O estabelecimento deve prever, em programa de autocontrole, o tempo máximo de permanência das aves nos galpões de espera."}, {"c": "dou-paragraph", "t": "§ 2º É proibida a permanência de veículos transportadores com aves fora dos galpões de espera."}, {"c": "dou-paragraph", "t": "Art. 81. O procedimento de descarregamento e pendura das aves deve atender à legislação de bem-estar animal, evitando o desconforto, dor ou injúria às aves."}, {"c": "dou-paragraph", "t": "Art. 82. As aves mortas durante o transporte ou na plataforma de recepção devem ser contabilizadas e registradas pelo estabelecimento, conforme normas específicas."}, {"c": "dou-paragraph", "t": "§ 1º No recebimento das aves, caso o estabelecimento constate violação dos percentuais de mortalidade previstos na legislação de saúde animal, deve comunicar imediatamente o Serviço de Inspeção Federal para serem realizadas as avaliações e providências cabíveis."}, {"c": "dou-paragraph", "t": "§ 2º Quando o Serviço de Inspeção Federal considerar necessária a avaliação das aves mortas, o estabelecimento deve disponibilizá-las para inspeção antes de descartá-las."}, {"c": "dou-paragraph", "t": "Art. 83. As caixas com aves vivas devem ser higienizadas logo após a pendura dessas aves."}, {"c": "dou-paragraph", "t": "Parágrafo único. É proibida a reutilização de caixas sujas para o transporte de aves vivas."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Insensibilização e Sangria"}, {"c": "dou-paragraph", "t": "Art. 84. Os métodos e procedimentos para insensibilização e sangria devem atender o estabelecido em legislação específica."}, {"c": "dou-paragraph", "t": "Art. 85. O sangue deve ser coletado de forma contínua, sendo proibido seu acúmulo neste setor."}, {"c": "dou-paragraph", "t": "Parágrafo único. O sangue pode ser destinado para produção de produtos não comestíveis ou outro destino previsto em normas específicas, desde que atendidos os requisitos higiênico-sanitários e de rastreabilidade."}, {"c": "dou-paragraph", "t": "Art. 86. A partir da sangria, todas as operações devem ser realizadas de forma contínua, não sendo permitido o retardamento ou acúmulo de aves em nenhuma de suas etapas até a entrada de seus produtos nas câmaras frigoríficas."}, {"c": "dou-paragraph", "t": "Art. 87. É permitida a lavagem das aves após a sangria e antes de entrarem no sistema de escaldagem, desde que não haja interrupção do fluxo de abate."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Escaldagem e Depenagem"}, {"c": "dou-paragraph", "t": "Art. 88. A escaldagem deve ser realizada logo após o término da sangria, sob condições estabelecidas de temperatura e tempo e ajustadas às características próprias das aves em processamento, com a remoção completa das penas das carcaças, conforme programa de autocontrole."}, {"c": "dou-paragraph", "t": "Art. 89. É proibida a introdução de aves ainda vivas no sistema de escaldagem e depenagem."}, {"c": "dou-paragraph", "t": "Art. 90. A renovação de água do tanque de escaldagem deve ser contínua, com água potável, de forma que em cada turno de trabalho seja renovado o correspondente ao seu volume total."}, {"c": "dou-paragraph", "t": "§ 1º A água desses equipamentos deve ser totalmente drenada para a higienização pré-operacional."}, {"c": "dou-paragraph", "t": "§ 2º A critério do Serviço de Inspeção Federal, a água do tanque de escaldagem pode ser totalmente drenada nos intervalos de turnos de trabalho, quando necessário."}, {"c": "dou-paragraph", "t": "Art. 91. A renovação de água dos equipamentos destinados à escaldagem de pés e cabeças deve ser contínua, de forma que em cada turno de trabalho seja renovado o correspondente ao seu volume total."}, {"c": "dou-paragraph", "t": "§ 1º A água desses equipamentos pode ser totalmente drenada para realização da higienização pré-operacional."}, {"c": "dou-paragraph", "t": "§ 2º A critério do serviço de inspeção federal, a água desses equipamentos pode ser totalmente drenada nos intervalos de turnos de trabalho quando necessário."}, {"c": "dou-paragraph", "t": "Art. 92. É proibida a adição de adjuvante de tecnologia, desinfetante, conservante ou qualquer outra substância na água utilizada nos tanques de escaldagem sem prévia autorização do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 93. Os pés destinados a fins comestíveis devem passar pela etapa de classificação prevista em programas de autocontrole."}, {"c": "dou-paragraph", "t": "Seção IV"}, {"c": "dou-paragraph", "t": "Evisceração"}, {"c": "dou-paragraph", "t": "Art. 94. No setor de evisceração são realizados os procedimentos operacionais necessários para a adequada eventração e evisceração das carcaças."}, {"c": "dou-paragraph", "t": "§ 1º Os procedimentos que devem ser realizados antes da entrada das carcaças no sistema de pré-resfriamento são:"}, {"c": "dou-paragraph", "t": "I - extração de cloaca;"}, {"c": "dou-paragraph", "t": "II - abertura do abdômen;"}, {"c": "dou-paragraph", "t": "III - eventração;"}, {"c": "dou-paragraph", "t": "IV - evisceração;"}, {"c": "dou-paragraph", "t": "V - extração dos pulmões;"}, {"c": "dou-paragraph", "t": "VI - extração de papo, esôfago e traquéia;"}, {"c": "dou-paragraph", "t": "VII - avaliação interna e externa quanto à presença de contaminação gastrointestinal e biliar visíveis; e"}, {"c": "dou-paragraph", "t": "VIII - lavagem final interna e externa das carcaças."}, {"c": "dou-paragraph", "t": "§ 2º É proibida a remoção, pelo estabelecimento, de partes ou vísceras das carcaças que sejam indispensáveis para identificação de lesões ou alterações nas linhas de inspeção post mortem e no Departamento de Inspeção Final."}, {"c": "dou-paragraph", "t": "§ 3º As carcaças e vísceras devem ser apresentadas em condições de serem examinadas de forma eficiente nas linhas de inspeção post mortem."}, {"c": "dou-paragraph", "t": "§ 4º É permitido o emprego de sistema adicional de lavagem de carcaças, como alternativa à prática do refile, atendido o Anexo I."}, {"c": "dou-paragraph", "t": "§ 5º É permitido o emprego de sistema lavagem externa por aspersão das carcaças, para remover contaminação por conteúdo gastrintestinal visível, anterior à inspeção post mortem, conforme autorizado pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 95. As operações de evisceração, sejam automatizadas ou não, devem atender os cuidados necessários para prevenir o rompimento de vísceras e o contato das carcaças com superfícies contaminadas."}, {"c": "dou-paragraph", "t": "Art. 96. É proibida a entrada de carcaças no sistema de pré-resfriamento por imersão que contenham no seu interior água residual de lavagem por aspersão e qualquer tipo de contaminação visível na sua superfície externa e interna."}, {"c": "dou-paragraph", "t": "Art. 97. As vísceras não comestíveis devem ser transferidas diretamente para a calha de evisceração e conduzidas aos depósitos coletores ou diretamente ao setor de produtos não comestíveis."}, {"c": "dou-paragraph", "t": "Art. 98. Os miúdos devem ser previamente preparados, lavados e processados em local adequado, antes do seu pré-resfriamento."}, {"c": "dou-paragraph", "t": "§ 1º As moelas devem ser abertas, permitindo sua lavagem completa e a remoção da cutícula."}, {"c": "dou-paragraph", "t": "§ 2º O coração deve ter o seu saco pericárdico removido."}, {"c": "dou-paragraph", "t": "§ 3º O fígado deve ter a sua vesícula biliar removida."}, {"c": "dou-paragraph", "t": "Art. 99. Os miúdos devem ser pré-resfriados imediatamente após a sua coleta e preparação."}, {"c": "dou-paragraph", "t": "Art. 100. Os pés e pescoço com ou sem cabeça, assim como outros cortes e partes de carcaças, quando removidos na linha de evisceração para fins comestíveis, devem ser imediatamente pré-resfriados."}, {"c": "dou-paragraph", "t": "Art. 101. Tanto a gordura cavitária quanto a de cobertura da moela podem ser utilizadas para fins comestíveis, quando removidas durante o processo de evisceração."}, {"c": "dou-paragraph", "t": "Art. 102. Os pulmões devem ser removidos através de sistema de vácuo ou mecânico."}, {"c": "dou-paragraph", "t": "Art. 103. A lavagem final por aspersão das carcaças antes do seu pré-resfriamento deve ser realizada por meio de equipamento destinado a lavar de forma eficiente as suas superfícies internas e externas."}, {"c": "dou-paragraph", "t": "§ 1º Deve ser instalado hidrômetro para controle do volume da água consumida de, no mínimo, 1,5 L (um litro e meio) por carcaça."}, {"c": "dou-paragraph", "t": "§ 2º A localização do equipamento para lavagem por aspersão das carcaças deve ser após a evisceração e imediatamente antes do sistema de pré-resfriamento, proibida qualquer manipulação das carcaças após o seu procedimento de lavagem."}, {"c": "dou-paragraph", "t": "Art. 104. Os folículos ovarianos podem ser coletados e destinados para fins comestíveis, desde que:"}, {"c": "dou-paragraph", "t": "I - a sua coleta seja realizada somente após a liberação das aves por parte do Serviço de Inspeção Federal;"}, {"c": "dou-paragraph", "t": "II - o produto seja resfriado imediatamente após a sua coleta, a uma temperatura máxima de 4,0 °C (quatro graus Celsius); e"}, {"c": "dou-paragraph", "t": "III - atenda ao disposto em norma específica."}, {"c": "dou-paragraph", "t": "Seção V"}, {"c": "dou-paragraph", "t": "Pré-resfriamento e gotejamento"}, {"c": "dou-paragraph", "t": "Art. 105. O pré-resfriamento consiste no rebaixamento da temperatura das carcaças e miúdos imediatamente após as etapas de evisceração."}, {"c": "dou-paragraph", "t": "Art. 106. Quando o pré-resfriamento for realizado por meio de sistema de imersão em água gelada e gelo, devem ser atendidos os seguintes critérios:"}, {"c": "dou-paragraph", "t": "I - a água de renovação do sistema de pré-resfriamento deve atender aos padrões de potabilidade estabelecidos em legislação específica;"}, {"c": "dou-paragraph", "t": "II - cada tanque do sistema de pré-resfriamento contínuo por imersão deve ser completamente esvaziado, limpo e desinfetado, pelo menos nos intervalos da higienização pré-operacional;"}, {"c": "dou-paragraph", "t": "III - o reaproveitamento da água no pré-resfriamento contínuo por imersão é permitido, desde que apresente os padrões de potabilidade estabelecidos após o seu tratamento;"}, {"c": "dou-paragraph", "t": "IV - a recirculação da água pré-resfriamento contínuo por imersão é permitida, sendo que a água a ser recirculada só pode retornar para o tanque anterior ou para o mesmo tanque da qual foi recolhida; e"}, {"c": "dou-paragraph", "t": "V - é permitido o reaproveitamento de águas servidas para condução de resíduos não comestíveis, desde que possua rede diferenciada e identificada para água não potável e que não haja risco de contaminação cruzada com os produtos."}, {"c": "dou-paragraph", "t": "Art. 107. A renovação de água dos pré-resfriadores contínuos, durante o abate, deve ser constante e em sentido contrário à movimentação das carcaças, de forma contracorrente, na proporção mínima de um litro e meio (1,5L) por carcaça no primeiro estágio e 1,0 L (um litro) no último estágio."}, {"c": "dou-paragraph", "t": "Parágrafo único. A temperatura da água residente, medida nos pontos de entrada e saída das carcaças do sistema de pré-resfriamento por imersão, não deve ser superior a 16,0 °C (dezesseis graus Celsius) e 4,0 °C (quatro graus Celsius), respectivamente no primeiro e último estágio, atendido o tempo máximo de permanência das carcaças no primeiro estágio de trinta minutos."}, {"c": "dou-paragraph", "t": "Art. 108. A renovação de água dos resfriadores de miúdos, cortes e gordura cavitária deve ser constante e em sentido contrário à movimentação das peças, de forma contracorrente, na proporção mínima de 1,5 L (um litro e meio) por quilograma de miúdo."}, {"c": "dou-paragraph", "t": "Parágrafo único. A temperatura da água residente nestes pré-resfriadores não deve ser superior a 4,0 °C (quatro graus Celsius)."}, {"c": "dou-paragraph", "t": "Art. 109. O tanque de pré-resfriamento das partes de carcaças liberadas pela inspeção post mortem deve ser dimensionado conforme a capacidade operacional e as características do tipo de ave abatida, sendo instalado de forma que garanta o fluxo contínuo e as condições higiênico-sanitárias durante todo o processo."}, {"c": "dou-paragraph", "t": "§ 1º A renovação de água destes resfriadores deve ser constante e em sentido contrário à movimentação das peças, contracorrente, na proporção mínima de 1,5 L/ Kg (um litro e meio por quilograma)."}, {"c": "dou-paragraph", "t": "§ 2º A temperatura da água residente nestes pré-resfriadores não deve ser superior a 4,0 °C (quatro graus Celsius)."}, {"c": "dou-paragraph", "t": "Art. 110. O volume de água utilizada para encher os tanques ou estágios dos pré-resfriadores por imersão pela primeira vez não deve ser incluído no cálculo da vazão."}, {"c": "dou-paragraph", "t": "Art. 111. Os estabelecimentos que atenderem aos critérios estabelecidos na avaliação microbiológica do desempenho higiênico-sanitário no processo de abate, conforme norma específica, podem estabelecer padrões de temperatura e vazão no sistema de pré-resfriamento contínuo diferentes dos estabelecidos nesta portaria."}, {"c": "dou-paragraph", "t": "Parágrafo único. Para padrões de temperatura e vazão no sistema de pré-resfriamento contínuo diferentes dos estabelecidos nesta portaria, o estabelecimento deve realizar a validação técnico-científica do processo, prevendo a sua forma de monitoramento, bem como comprovar a manutenção do desempenho higiênico-sanitário e da segurança do produto."}, {"c": "dou-paragraph", "t": "Art. 112. Ao final do sistema de pré-resfriamento, as carcaças, partes de carcaças e miúdos devem atingir uma temperatura máxima de 7,0 °C (sete graus Celsius) medidos na intimidade da peça."}, {"c": "dou-paragraph", "t": "Parágrafo único. Ao final do sistema de pré-resfriamento, é permitida a temperatura máxima de 10,0 °C (dez graus Celsius), na intimidade da peça, para as carcaças destinadas diretamente à embalagem primária e ao congelamento."}, {"c": "dou-paragraph", "t": "Art. 113. O gelo utilizado no estabelecimento deve ser produzido com água potável, atendida a legislação específica."}, {"c": "dou-paragraph", "t": "Parágrafo único. O gelo adicionado aos sistemas de pré-resfriamento por imersão pode ser considerado nos cálculos das quantidades estabelecidas para renovação constante de água no sistema, desde que o seu autocontrole seja auditável."}, {"c": "dou-paragraph", "t": "Art. 114. É proibida a adição de adjuvante de tecnologia, desinfetante, conservante ou qualquer outra substância na água utilizada no pré-resfriamento sem a prévia autorização do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 115. A etapa de gotejamento visa escorrimento de parte da água absorvida pela carcaça durante o método de pré-resfriamento por imersão."}, {"c": "dou-paragraph", "t": "Art. 116. Ao final do gotejamento, os estabelecimentos devem controlar os índices de absorção de água nas carcaças submetidas ao pré-resfriamento por imersão, por meio de teste de absorção."}, {"c": "dou-paragraph", "t": "§ 1º A absorção da água nas carcaças submetidas ao pré-resfriamento por imersão não deve ultrapassar a 8,0 % (oito por cento) de seus pesos."}, {"c": "dou-paragraph", "t": "§ 2º O teste de absorção é baseado na comparação dos pesos das carcaças, identificadas, antes e depois do pré-resfriamento por imersão."}, {"c": "dou-paragraph", "t": "§ 3º A frequência dos testes de absorção deve ser estabelecida nos programas de autocontrole do estabelecimento, de forma que os índices de absorção não ultrapassem o limite estabelecido durante todo o processo de abate."}, {"c": "dou-paragraph", "t": "§ 4º A metodologia do teste de absorção consta no Anexo II."}, {"c": "dou-paragraph", "t": "Art. 117. Os estabelecimentos devem controlar a quantidade de água resultante do descongelamento de carcaças congeladas pelo teste de gotejamento (Dripping Test)."}, {"c": "dou-paragraph", "t": "§ 1º O resultado do teste de gotejamento, expresso em percentagem do peso da carcaça, com todos os miúdos e partes comestíveis presentes na embalagem, não deve ultrapassar o valor limite de 6,0 % (seis por cento)."}, {"c": "dou-paragraph", "t": "§ 2º A frequência dos testes de gotejamento deve ser estabelecida nos programas de autocontrole do estabelecimento."}, {"c": "dou-paragraph", "t": "§ 3º A metodologia do teste de gotejamento consta no Anexo III."}, {"c": "dou-paragraph", "t": "Art. 118. Os estabelecimentos devem controlar o teor total de água contida em carcaças e cortes de aves da espécie Gallus gallus (frango, galo, galinha e galeto), conforme Anexo IV."}, {"c": "dou-paragraph", "t": "Seção VI"}, {"c": "dou-paragraph", "t": "Classificação e embalagem"}, {"c": "dou-paragraph", "t": "Art. 119. A classificação de carcaças por peso pode ser realizada antes ou após a sua embalagem."}, {"c": "dou-paragraph", "t": "Art. 120. Carcaças, cortes ou partes de carcaças e miúdos devem ser comercializadas embaladas e rotuladas."}, {"c": "dou-paragraph", "t": "Art. 121. No setor de embalagem secundária, é proibida a entrada produtos sem a devida embalagem primária."}, {"c": "dou-paragraph", "t": "Parágrafo único. O acondicionamento dos produtos em embalagens secundárias deve ser realizado em uma área distinta daquela onde é realizada embalagem primária."}, {"c": "dou-paragraph", "t": "Art. 122. Os miúdos, partes de carcaça e cortes, comercializadas no interior das carcaças, devem receber embalagem própria."}, {"c": "dou-paragraph", "t": "Art. 123. É permitida, para fins de acondicionamento e transporte, a reutilização de caixas ou recipientes desde que estejam íntegros e higienizados."}, {"c": "dou-paragraph", "t": "Art. 124. Carcaças, partes de carcaças, cortes, miúdos e produtos devem ser comercializadas embaladas e rotuladas conforme normas específicas."}, {"c": "dou-paragraph", "t": "Art. 125. É proibida a incorporação de água, gelo ou qualquer substância que aumente irregularmente o peso do produto embalado."}, {"c": "dou-paragraph", "t": "Seção VII"}, {"c": "dou-paragraph", "t": "Cortes e desossa"}, {"c": "dou-paragraph", "t": "Art. 126. A temperatura das carnes na entrada deste setor e durante a sua manipulação não pode exceder 7,0 °C (sete graus Celsius)."}, {"c": "dou-paragraph", "t": "§ 1º O resfriamento dos cortes a 4,0 °C (quatro graus Celsius) deve ser atingido no menor intervalo de tempo possível."}, {"c": "dou-paragraph", "t": "§ 2º A variação aceitável de temperatura dos produtos no ambiente de corte e manipulação deve ser estabelecida e validada com base em microbiologia preditiva, modelos matemáticos e softwares (derivados de dados experimentais) para predizer quantitativamente a multiplicação de patógenos e a produção de toxinas, sob condições determinadas de tempo, temperatura, pH, atividade de água e outros parâmetros, em estudos específicos por processos e produtos."}, {"c": "dou-paragraph", "t": "§ 3º Os binômios validados de que trata o § 2º devem garantir a ausência de multiplicação de patógenos e produção de toxinas, atendido o resfriamento dos cortes a 4,0°C (quatro graus Celsius), no menor intervalo de tempo possível."}, {"c": "dou-paragraph", "t": "Art. 127. Para o processamento de produtos cozidos, defumados, curados, esterilizados e outros, devem ser atendidas as normas específicas do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Seção VIII"}, {"c": "dou-paragraph", "t": "Frigorificação"}, {"c": "dou-paragraph", "t": "Art. 128. O resfriamento é o processo de refrigeração e manutenção da temperatura entre 0,0 °C (zero graus Celsius) a 4,0 °C (quatro graus Celsius) dos produtos (carcaças, cortes ou recortes, miúdos e derivados)."}, {"c": "dou-paragraph", "t": "Art. 129. O congelamento é o processo de refrigeração e manutenção a uma temperatura não maior que -12,0 °C (doze graus Celsius negativos), dos produtos (carcaças, cortes ou recortes, miúdos e derivados)."}, {"c": "dou-paragraph", "t": "Art. 130. As antecâmaras devem ser utilizadas apenas como área de circulação, sendo proibida a sua utilização para outra finalidade."}, {"c": "dou-paragraph", "t": "Parágrafo único. As antecâmaras devem ser climatizadas conforme previsto em programas de autocontrole."}, {"c": "dou-paragraph", "t": "Art. 131. Os produtos armazenados nas câmaras de resfriamento e de congelamento devem estar embalados e rotulados, sobre estrados, garantindo sua segurança e rastreabilidade."}, {"c": "dou-paragraph", "t": "§ 1º É proibido depositar produtos ou caixas contendo produtos comestíveis diretamente no piso."}, {"c": "dou-paragraph", "t": "§ 2º Nas áreas frigorificadas é permitido o uso de estrados de madeira, desde que os produtos ali depositados estejam embalados e que não haja comprometimento de sua segurança."}, {"c": "dou-paragraph", "t": "Art. 132. Os produtos armazenados nas câmaras de resfriamento devem apresentar temperatura entre -1,0 °C (um grau Celsius negativo) a 4,0 °C (quatro graus Celsius)."}, {"c": "dou-paragraph", "t": "Art. 133. A armazenagem de produtos congelados deve ser realizada em câmaras próprias, com temperatura nunca superior a -18,0 °C (dezoito graus Celsius negativos)."}, {"c": "dou-paragraph", "t": "Parágrafo único. É proibido o congelamento de produtos nas câmaras de estocagem."}, {"c": "dou-paragraph", "t": "Art. 134. Os produtos congelados devem apresentar, na sua intimidade, temperatura de -12,0 °C (doze graus Celsius negativos) ou mais frio."}, {"c": "dou-paragraph", "t": "CAPÍTULO V"}, {"c": "dou-paragraph", "t": "PROCEDIMENTOS DE INSPEÇÃO ANTE MORTEM E POST MORTEM"}, {"c": "dou-paragraph", "t": "Art. 135. O estabelecimento deve providenciar a estrutura física, os equipamentos e o pessoal necessário para a execução dos procedimentos de inspeção ante mortem e post mortem."}, {"c": "dou-paragraph", "t": "Art. 136. O abate do lote de aves somente pode ser iniciado após a realização do exame ante mortem documental pelo Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal."}, {"c": "dou-paragraph", "t": "Art. 137. Os procedimentos de inspeção ante mortem e post mortem constam em manuais do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Inspeção ante mortem"}, {"c": "dou-paragraph", "t": "Art. 138. A inspeção ante mortem deve garantir que somente aves saudáveis e aptas ao abate sejam destinadas ao consumo humano."}, {"c": "dou-paragraph", "t": "Parágrafo único. São objetivos da inspeção ante mortem:"}, {"c": "dou-paragraph", "t": "I - examinar visualmente todos os lotes de aves destinadas ao abate;"}, {"c": "dou-paragraph", "t": "II - garantir que informações clínicas e sanitárias relevantes tenham sido avaliadas para subsidiar o julgamento sanitário;"}, {"c": "dou-paragraph", "t": "III - evitar a contaminação no processo de abate segregando os lotes de aves doentes e os lotes de aves que não cumpriram o jejum, conforme programa de autocontrole e legislação específica;"}, {"c": "dou-paragraph", "t": "IV - garantir que para aves machucadas, em sofrimento ou em agonia, sejam atendidos os princípios de bem-estar animal;"}, {"c": "dou-paragraph", "t": "V - identificar aves com sinais clínicos de doenças de notificação obrigatória ou com diagnóstico laboratorial confirmado; e"}, {"c": "dou-paragraph", "t": "VI - identificar aves tratadas com medicamentos veterinários ou expostas a substâncias que impliquem em risco à saúde pública."}, {"c": "dou-paragraph", "t": "Art. 139. A inspeção ante mortem deve ser realizada em, no mínimo, duas etapas:"}, {"c": "dou-paragraph", "t": "I - inspeção documental prévia, antes da chegada das aves ao estabelecimento; e"}, {"c": "dou-paragraph", "t": "II - inspeção no local, por ocasião do recebimento, permanência nos galpões de espera, descarga e imediatamente antes do abate, compreendendo a avaliação documental complementar e a avaliação visual e clínica das aves."}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Inspeção documental prévia"}, {"c": "dou-paragraph", "t": "Art. 140. A inspeção ante mortem documental consiste na avaliação das informações referentes à cadeia produtiva, saúde pública e saúde animal, que devem ser disponibilizadas ao Serviço de Inspeção Federal em documento padronizado."}, {"c": "dou-paragraph", "t": "Art. 141. Na inspeção ante mortem documental deve ser avaliado o seguinte:"}, {"c": "dou-paragraph", "t": "I - a declaração de alimentação e origem dos insumos, quando requerido pelo mercado importador ou norma específica;"}, {"c": "dou-paragraph", "t": "II - os medicamentos administrados, com datas de sua administração às aves e seus respectivos períodos de carência;"}, {"c": "dou-paragraph", "t": "III - a ocorrência de doenças ou problemas no lote de aves;"}, {"c": "dou-paragraph", "t": "IV - os resultados de quaisquer análises de amostras coletadas das aves s ou de outras amostras para efeitos de diagnóstico de importância para a saúde pública ou animal;"}, {"c": "dou-paragraph", "t": "V - o índice de mortalidade do lote; e"}, {"c": "dou-paragraph", "t": "VI - informações complementares exigidas pelo Serviço de Inspeção Federal ou por programas oficiais."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Inspeção no local"}, {"c": "dou-paragraph", "t": "Art. 142. A avaliação clínica ante mortem das aves pode ser realizada com as aves em repouso e em movimento, em grupo ou individualmente, conforme a necessidade de melhor observação e diagnóstico."}, {"c": "dou-paragraph", "t": "Art. 143. Na avaliação clínica ante mortem devem ser observados, no mínimo:"}, {"c": "dou-paragraph", "t": "I - o comportamento geral das aves;"}, {"c": "dou-paragraph", "t": "II - o estado nutricional;"}, {"c": "dou-paragraph", "t": "III - as condições de limpeza e integridade da pele;"}, {"c": "dou-paragraph", "t": "IV - sinais de doença ou anormalidades; e"}, {"c": "dou-paragraph", "t": "V - índice de mortalidade do lote dos animais."}, {"c": "dou-paragraph", "t": "Parágrafo único. Entre as anormalidades a serem avaliadas incluem-se:"}, {"c": "dou-paragraph", "t": "I - alterações respiratórias, digestórias e neurológicas;"}, {"c": "dou-paragraph", "t": "II - alterações de comportamento;"}, {"c": "dou-paragraph", "t": "III - alterações de locomoção;"}, {"c": "dou-paragraph", "t": "IV - alterações de postura;"}, {"c": "dou-paragraph", "t": "V - alterações de secreção, excreção ou protusão em orifícios naturais; e"}, {"c": "dou-paragraph", "t": "VI - alterações de cor e odor compatíveis com processos patológicos ou com contaminação."}, {"c": "dou-paragraph", "t": "Art. 144. Todos os achados clínicos relevantes e as destinações atribuídas aos lotes devem ser registrados em planilhas ou sistemas, conforme estabelecido em manuais do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 145. Com base nos achados clínicos e nas informações disponibilizadas pela cadeia produtiva, o Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal pode, caso necessário, determinar a velocidade, a ordenação e a segregação dos lotes no abate, considerando a necessidade de minimizar a contaminação cruzada, preservar as condições higiênico-sanitárias e o bem-estar animal."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Abate de emergência, eutanásia e necropsia"}, {"c": "dou-paragraph", "t": "Art. 146. O Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal deve indicar e registrar, o destino das aves para:"}, {"c": "dou-paragraph", "t": "I - abate normal, o qual é o abate das aves fisiologicamente normais, aparentemente saudáveis, consideradas aptas ao abate pelo Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal;"}, {"c": "dou-paragraph", "t": "II - abate de emergência mediato, o qual é o abate realiza em separado, nas instalações comuns de abate, das aves excluídas do abate normal, após inspeção ante mortem, com o objetivo de minimizar a contaminação cruzada no processo, devendo ser seguido da higienização completa das instalações e equipamentos;"}, {"c": "dou-paragraph", "t": "III - abate de emergência imediato, o qual é o abate realizado nas instalações comuns de abate das aves cujo estado clínico recomende este procedimento, após a inspeção ante mortem, devendo ser o mais breve possível; ou"}, {"c": "dou-paragraph", "t": "IV - necropsia, a qual é procedimento técnico investigatório realizado pelo Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal, devendo ocorrer na sala de necropsia, conforme previsto em manuais do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 147. Os registros oficiais desta etapa devem ser realizados conforme estabelecido em manuais do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Inspeção post mortem"}, {"c": "dou-paragraph", "t": "Art. 148. A execução da inspeção de carcaças, partes da carcaça e órgãos nas linhas de inspeção deve ser realizada pela equipe do Serviço de Inspeção Federal."}, {"c": "dou-paragraph", "t": "Art. 149. O Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal realizará as medidas necessárias para garantir a adequada realização do exame post mortem, levando em consideração:"}, {"c": "dou-paragraph", "t": "I - a condição sanitária do lote;"}, {"c": "dou-paragraph", "t": "II - a quantidade e a capacidade técnica de auxiliares disponíveis para realizar os procedimentos de inspeção;"}, {"c": "dou-paragraph", "t": "III - a adequação da velocidade de abate aos procedimentos necessários;"}, {"c": "dou-paragraph", "t": "IV - a manutenção da correlação e sincronia entre carcaça, suas partes e órgãos; e"}, {"c": "dou-paragraph", "t": "V - o atendimento, pelo estabelecimento, aos requisitos estruturais, inclusive de espaço necessário e adequado, e a disposição de utensílios de trabalho para a realização dos procedimentos de inspeção."}, {"c": "dou-paragraph", "t": "Art. 150. A inspeção post mortem deve ser realizada no ponto de pré-inspeção, nas linhas de inspeção A, B e C, bem como no Departamento de Inspeção Final."}, {"c": "dou-paragraph", "t": "Art. 151. Os apontamentos das condenações e destinações, realizados no ponto de pré-inspeção, nas linhas de inspeção e no Departamento de Inspeção Final, devem ser realizados de forma precisa e fidedigna nos sistemas de registro disponibilizado pelo estabelecimento, garantindo que as informações sejam confiáveis e auditáveis."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os sistemas de registro previstos no caput devem atender ao estabelecido em manuais do Departamento de Inspeção de Produtos de Origem Animal"}, {"c": "dou-paragraph", "t": "Art. 152. Ao final do abate de cada lote, o Serviço de Inspeção Federal deve compilar os apontamentos das alterações encontradas nas linhas de inspeção, registrando-os conforme manuais do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 153. Durante a supervisão das atividades realizadas nas linhas de inspeção, o Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal deve avaliar:"}, {"c": "dou-paragraph", "t": "I - a execução das linhas de inspeção, conforme as técnicas estabelecidas nos manuais do Departamento de Inspeção de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "II - a capacidade de detecção de alterações e sua destinação adequada; e"}, {"c": "dou-paragraph", "t": "III - o registro inequívoco das causas de condenação e destinação no ponto de pré-inspeção, nas linhas de inspeção e no Departamento de Inspeção Final."}, {"c": "dou-paragraph", "t": "Art. 154. Lesões atípicas, não caracterizadas, ou compatíveis com doenças de notificação obrigatória devem ser avaliadas pelo Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária ou Médico-Veterinário Integrante da Equipe do Serviço de Inspeção Federal para a destinação."}, {"c": "dou-paragraph", "t": "Art. 155. A inspeção post mortem, no ponto de pré-inspeção, consiste no exame inicial das carcaças inteiras, antes da remoção de qualquer parte comestível, com a finalidade de identificar alterações evidentes de caráter sistêmico, generalizado, com comprometimento da carcaça, que demandem a condenação total, bem como identificar falhas operacionais e situações que possam comprometer as condições sanitárias do abate."}, {"c": "dou-paragraph", "t": "§ 1º O exame no ponto de pré-inspeção é realizado por observação visual sistemática, devendo considerar, no mínimo:"}, {"c": "dou-paragraph", "t": "I - a condição geral das carcaças, quanto ao aspecto, à coloração e à integridade;"}, {"c": "dou-paragraph", "t": "II - lesões na articulação tibiotársica capazes de contaminar o disco de corte de pés;"}, {"c": "dou-paragraph", "t": "III - alterações sistêmicas e generalizadas;"}, {"c": "dou-paragraph", "t": "IV - contaminações grosseiras ou sujidades incompatíveis com a continuidade do seu processamento; e"}, {"c": "dou-paragraph", "t": "V - falhas no processo de sangria, escaldagem ou depenagem que justifiquem a condenação total neste ponto."}, {"c": "dou-paragraph", "t": "§ 2º Nesta etapa, as carcaças nas quais forem identificadas lesões generalizadas devem ser condenadas totalmente."}, {"c": "dou-paragraph", "t": "§ 3º O ponto de pré-inspeção pode ser dispensado em processo de abate que mantenha todas as partes das carcaças até a sala de evisceração."}, {"c": "dou-paragraph", "t": "§ 4º Excepcionalmente, por questões religiosas e de sangria manual, as carcaças sem qualquer alteração sistêmica perceptível que chegarem à pré-inspeção sem a cabeça, por falha tecnológica do processo de sangria e depenagem, podem seguir no fluxo de abate."}, {"c": "dou-paragraph", "t": "§ 5º No ponto de pré-inspeção é proibido o procedimento de cortes ou a remoção de partes da carcaça pelo auxiliar de inspeção."}, {"c": "dou-paragraph", "t": "Art. 156. A Inspeção post mortem é realizada em três etapas:"}, {"c": "dou-paragraph", "t": "I - na linha de inspeção A, exame interno, é realizada através da visualização da cavidade torácica e abdominal, incluindo os pulmões, sacos aéreos, rins, órgãos sexuais;"}, {"c": "dou-paragraph", "t": "II - a linha de inspeção B, exame de vísceras, é realizada a visualização do coração, fígado, moela, baço, intestinos, ovários e ovidutos nas poedeiras, da seguinte forma:"}, {"c": "dou-paragraph", "t": "a) com visualização do aspecto, cor, forma e tamanho; e"}, {"c": "dou-paragraph", "t": "b) com palpação e, conforme o caso, verificação de odores e incisão."}, {"c": "dou-paragraph", "t": "III - a linha C, exame externo, é realizada através da visualização das superfícies externas, tais como, por exemplo, pele e articulações, sendo facultada a remoção de contusões, membros fraturados, abscessos superficiais e localizados, calosidades e outras alterações, desde que haja estrutura adequada, tempo suficiente e sistema para registro das condenações."}, {"c": "dou-paragraph", "t": "Art. 157. O tempo necessário para a realização das atividades de inspeção deve ser de, no mínimo, dois segundos por ave, por auxiliar de inspeção, e em cada linha de inspeção."}, {"c": "dou-paragraph", "t": "Parágrafo único. O tempo mínimo de que trata o caput serve como base para o cálculo do número de auxiliares de inspeção e da capacidade de abate, conforme Anexo V."}, {"c": "dou-paragraph", "t": "Art. 158. A inspeção post mortem no Departamento de Inspeção Final consiste na avaliação final das carcaças e de suas partes e miúdos, após a sua prévia segregação nas linhas de inspeção, para exame mais detalhado, para o julgamento e a destinação dos produtos, garantindo a sua aptidão para o consumo humano ou a sua correta destinação."}, {"c": "dou-paragraph", "t": "§ 1º A inspeção no Departamento de Inspeção Final deve ser realizada por exame visual detalhado, podendo ser complementada por palpação, incisão ou outros procedimentos técnicos, sempre que necessário, sob responsabilidade do Auditor Fiscal Federal Agropecuário com formação em medicina veterinária ou do médico-veterinário integrante da equipe do Serviço de Inspeção Federal."}, {"c": "dou-paragraph", "t": "§ 2º No Departamento de Inspeção Final devem ser avaliados, no mínimo:"}, {"c": "dou-paragraph", "t": "I - a conformidade das carcaças quanto às destinações definidas nas etapas anteriores;"}, {"c": "dou-paragraph", "t": "II - a adequada remoção de partes condenadas ou submetidas a aproveitamento condicional;"}, {"c": "dou-paragraph", "t": "III - a ausência de alterações remanescentes nas carcaças, suas partes e miúdos, liberados ao consumo humano; e"}, {"c": "dou-paragraph", "t": "IV - a adequada destinação das carcaças, suas partes e miúdos considerados impróprios para o consumo humano, na forma em que se apresentam."}, {"c": "dou-paragraph", "t": "§ 3º O Departamento de Inspeção Final constitui instância conclusiva da inspeção post mortem, cabendo ao Auditor Fiscal Federal Agropecuário com formação em medicina veterinária ou médico-veterinário integrante da equipe do Serviço de Inspeção Federal a decisão final quanto à destinação das carcaças, suas partes e miúdos."}, {"c": "dou-paragraph", "t": "§ 4° As operações do Departamento de Inspeção Final envolvendo corte nas carcaças devem ser aquelas exclusivamente destinadas à retirada de partes condenadas, sendo proibidas operações de espostejamento ou cortes das partes aptas ao consumo, as quais devem ser realizadas em etapas posteriores."}, {"c": "dou-paragraph", "t": "§ 5° As partes de aves consideradas aptas ao consumo devem ser encaminhadas imediatamente ao sistema de pré-resfriamento específico para as partes de carcaças liberadas pela inspeção post mortem e devem ser tratadas na sala de cortes, ambiente isolado e climatizado, salvo opção do estabelecimento em aplicar destinos mais restritivos para estes casos."}, {"c": "dou-paragraph", "t": "Art. 159. As atividades operacionais nas linhas de inspeção, pré-inspeção e Departamento de Inspeção Final estão sob supervisão do Serviço de Inspeção Federal, sendo proibida qualquer interferência do estabelecimento nos critérios de julgamento e destinação adotados pelos auxiliares de inspeção."}, {"c": "dou-paragraph", "t": "Parágrafo único. Eventuais contestações quanto aos critérios de julgamento e condenação adotados nos locais privativos da inspeção devem ser formalizadas ao Serviço de Inspeção Federal, por escrito, através de seu Responsável Técnico e do médico veterinário do estabelecimento, com embasamento técnico e legal."}, {"c": "dou-paragraph", "t": "CAPÍTULO VI"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES FINAIS"}, {"c": "dou-paragraph", "t": "Art. 160. Os casos omissos e as dúvidas em relação à aplicação desta portaria são resolvidos pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 161. Ficam revogadas:"}, {"c": "dou-paragraph", "t": "I - a Portaria SDA/MAPA nº 210, de 10 de novembro de 1998;"}, {"c": "dou-paragraph", "t": "II - a Portaria SDA/MAPA nº 557, de 30 de março de 2022; e"}, {"c": "dou-paragraph", "t": "III - a Resolução SDA/MAPA n° 4, de 4 de outubro de 2011."}, {"c": "dou-paragraph", "t": "Art. 162. Esta portaria entra em vigor em trezentos e sessenta e cinco dias após a data de sua publicação."}, {"c": "assina", "t": "CARLOS GOULART"}, {"c": "cargo", "t": "Secretário de Defesa Agropecuária"}, {"c": "dou-paragraph", "t": "ANEXO I"}, {"c": "dou-paragraph", "t": "SISTEMA DE LAVAGEM DE ALTA PRESSÃO DE CARCAÇAS PARA REMOÇÃO DA CONTAMINAÇÃO VISÍVEL POR CONTEÚDO GASTRINTESTINAL, COMO ALTERNATIVA À PRÁTICA DO REFILE"}, {"c": "dou-paragraph", "t": "1. É permitido o emprego do sistema de lavagem de carcaças de alta pressão no processo de abate de aves para remover a contaminação por conteúdo gastrintestinal visível presente nas superfícies internas e externas das carcaças, como alternativa à prática do refile."}, {"c": "dou-paragraph", "t": "2. A utilização deste sistema fica condicionada à apresentação de protocolo validado cientificamente, a ser verificado pelo Serviço de Inspeção Federal nas fiscalizações de rotina, de forma a garantir a ausência de contaminação por conteúdo gastrintestinal visível nas superfícies externas e internas das carcaças durante o processo de abate de aves, incluindo, pelo menos:"}, {"c": "dou-paragraph", "t": "- o tempo de exposição das carcaças a lavagem;"}, {"c": "dou-paragraph", "t": "- o volume de água utilizado por carcaça;"}, {"c": "dou-paragraph", "t": "- a disposição das carcaças no interior da cabine de lavagem;"}, {"c": "dou-paragraph", "t": "- a localização e número de aspersões, a pressão e direcionamento dos jatos d'água;"}, {"c": "dou-paragraph", "t": "- as análises microbiológicas para controle de higiene e qualidade do processo de abate e segurança dos produtos;"}, {"c": "dou-paragraph", "t": "- a descrição dos procedimentos de monitoramento e verificação dos requisitos; e"}, {"c": "dou-paragraph", "t": "- a descrição das ações preventivas e corretivas no caso da identificação de desvios na execução da lavagem de carcaça objeto desta resolução."}, {"c": "dou-paragraph", "t": "2.1. O estabelecimento, por meio dos seus programas de autocontrole, deve ser capaz de identificar a causa raiz de possíveis desvios."}, {"c": "dou-paragraph", "t": "2.2. As ações preventivas e corretivas devem ser aplicadas na causa raiz do desvio, incidindo sobre processo e produto."}, {"c": "dou-paragraph", "t": "2.3. O emprego deste sistema não pode ser compensatório às falhas dos procedimentos sanitários operacionais de abate."}, {"c": "dou-paragraph", "t": "3. O sistema de lavagem de carcaças deve estar localizado após a inspeção post mortem e antes da lavagem final por aspersão das carcaças prevista nesta portaria."}, {"c": "dou-paragraph", "t": "4. Os estabelecimentos que pretendem utilizar este sistema devem realizar revalidação do plano de análise de perigos e pontos críticos de controle, revisando, sempre que necessário:"}, {"c": "dou-paragraph", "t": "- sua análise de perigos;"}, {"c": "dou-paragraph", "t": "- limites críticos;"}, {"c": "dou-paragraph", "t": "- procedimentos de monitoramento e verificação; e"}, {"c": "dou-paragraph", "t": "- geração e manutenção de registros e de ações corretivas e preventivas no caso da identificação de desvios de processo."}, {"c": "dou-paragraph", "t": "ANEXO II"}, {"c": "dou-paragraph", "t": "TESTE DE ABSORÇÃO"}, {"c": "dou-paragraph", "t": "1. O controle aqui especificado refere-se à água absorvida durante o pré-resfriamento por imersão que está diretamente relacionado principalmente com a temperatura da água dos resfriadores, tempo de permanência no sistema, tipo de corte abdominal, injeção de ar no sistema (\"borbulhamento\") e outros fatores menos significativos."}, {"c": "dou-paragraph", "t": "2. A quantidade de água determinada por este método exprime-se em percentagem do peso total da carcaça de ave no limite máximo de 8,0 % (oito por cento) de seus pesos."}, {"c": "dou-paragraph", "t": "3. Técnica:"}, {"c": "dou-paragraph", "t": "Baseia-se na comparação dos pesos das carcaças identificadas, antes e depois do pré-resfriamento por imersão:"}, {"c": "dou-paragraph", "t": "3.1 Número de carcaças: no mínimo dez carcaças em cada teste;"}, {"c": "dou-paragraph", "t": "3.2 Separar as carcaças a serem testados após a saída do último chuveiro da calha de evisceração;"}, {"c": "dou-paragraph", "t": "3.3 Prover o prévio escorrimento da água retida nas cavidades;"}, {"c": "dou-paragraph", "t": "3.4 Pesar, individual ou coletivamente, as carcaças a serem testadas, determinando assim o peso inicial (Pi);"}, {"c": "dou-paragraph", "t": "3.5 Identificar as carcaças em teste antes de entrarem no sistema de pré-resfriamento por imersão;"}, {"c": "dou-paragraph", "t": "3.6 Retirar as carcaças em teste para pesagem somente após o gotejamento das mesmas;"}, {"c": "dou-paragraph", "t": "3.7 Pesar, individual ou coletivamente, as carcaças em teste, determinando assim o peso final (Pf); e"}, {"c": "dou-paragraph", "t": "3.8 O percentual de água absorvida (A) durante o processamento é calculado multiplicando-se a diferença (D) entre peso final (p f ) e peso inicial (p i ) por cem (100) e dividindo pelo peso inicial (p i )."}, {"c": "dou-paragraph", "t": "FÓRMULA:"}, {"c": "dou-paragraph", "t": "D x 100"}, {"c": "dou-paragraph", "t": "A= ----------------"}, {"c": "dou-paragraph", "t": "P i"}, {"c": "dou-paragraph", "t": "Sendo D = P f - P i"}, {"c": "dou-paragraph", "t": "4. Frequência dos testes:"}, {"c": "dou-paragraph", "t": "Dentro da verificação oficial do autocontrole relativo aos controles de composição de produtos e prevenção de fraude."}, {"c": "dou-paragraph", "t": "ANEXO III"}, {"c": "dou-paragraph", "t": "TESTE DE GOTEJAMENTO (DRIPPING TEST)"}, {"c": "dou-paragraph", "t": "1. Princípio"}, {"c": "dou-paragraph", "t": "1.1. Baseia-se na determinação gravimétrica do teor de líquido perdido pelas aves congeladas no degelo em condições padronizadas."}, {"c": "dou-paragraph", "t": "1.2. O resultado do ensaio é a média aritmética do percentual de líquido perdido de seis carcaças."}, {"c": "dou-paragraph", "t": "2. Campo de aplicação"}, {"c": "dou-paragraph", "t": "2.2. Carcaças de aves congeladas."}, {"c": "dou-paragraph", "t": "3. Materiais e equipamentos"}, {"c": "dou-paragraph", "t": "3.1. Balança com resolução mínima de 0,1g;"}, {"c": "dou-paragraph", "t": "3.2. Barbante;"}, {"c": "dou-paragraph", "t": "3.3. Termômetro de superfície ou de infravermelho;"}, {"c": "dou-paragraph", "t": "3.4. Banho com circulação de água, controlada termostaticamente à temperatura de 42,0 ± 2,0 °C (Quarenta de dois graus Celsius com desvio de dois graus Celsius para mais ou para menos), e volume de água não inferior a oito vezes o volume das carcaças a serem controladas;"}, {"c": "dou-paragraph", "t": "3.5. Guias ou pesos para manter as carcaças mergulhadas verticalmente;"}, {"c": "dou-paragraph", "t": "3.6. Sacos plásticos, resistentes e impermeáveis com capacidade suficiente para conter a carcaça e permitir um fechamento seguro; e"}, {"c": "dou-paragraph", "t": "3.7. Toalhas de tecido ou papel para enxugar a carcaça."}, {"c": "dou-paragraph", "t": "4. Reagentes e soluções"}, {"c": "dou-paragraph", "t": "4.1. Não aplicável."}, {"c": "dou-paragraph", "t": "5. Preparo da amostra"}, {"c": "dou-paragraph", "t": "5.1 As carcaças não podem sofrer descongelamento desde a coleta até sua recepção no laboratório, devendo ser mantidas em estado físico congelado sólido. A análise será iniciada estando as aves a uma temperatura de -12,0 ± 1,0 °C, medida em sua superfície externa."}, {"c": "dou-paragraph", "t": "6. Procedimento"}, {"c": "dou-paragraph", "t": "6.1. Enxugar o lado externo da embalagem de modo a eliminar todo o líquido e gelo aderido;"}, {"c": "dou-paragraph", "t": "6.2. Pesar a ave, obtendo-se M₀ ;"}, {"c": "dou-paragraph", "t": "6.3. Retirar a carcaça congelada de dentro da embalagem (com as vísceras, se presentes), enxugar a embalagem e pesá-la, obtendo-se M₁ ;"}, {"c": "dou-paragraph", "t": "6.4. Introduzir a carcaça, com os miúdos, num saco plástico com a cavidade abdominal voltada para o fundo do saco plástico e fechá-lo tendo o cuidado de retirar o excesso de ar por meio de pressão manual;"}, {"c": "dou-paragraph", "t": "6.5. Mergulhar completamente no banho a parte do saco que contêm a carcaça e as vísceras, de tal maneira que a água não penetre no interior do mesmo. Os sacos individuais não devem tocar uns nos outros;"}, {"c": "dou-paragraph", "t": "6.6. Repetir este procedimento para as outras cinco carcaças;"}, {"c": "dou-paragraph", "t": "6.7. Manter os sacos no banho de água a 42,0 ± 2,0 °C (Quarenta de dois graus Celsius com desvio de dois graus Celsius para mais ou para menos) com circulação contínua de acordo com os tempos definidos na tabela \"Tempos de imersão de acordo com a massa da ave\" a seguir."}, {"c": "dou-paragraph", "t": "6.8. Após o período de imersão, retirar o saco plástico do banho, abrir um orifício na parte inferior de modo que a água liberada pelo descongelamento possa escorrer e deixar à temperatura ambiente entre 18,0 °C (dezoito graus Celsius) e 25,0 °C (Vinte e cinco Graus Celsius) por no mínimo sessenta minutos;"}, {"c": "dou-paragraph", "t": "6.9. Retirar a carcaça descongelada do saco e as vísceras da cavidade torácica e enxugar a carcaça interna e externamente;"}, {"c": "dou-paragraph", "t": "6.10. Perfurar o invólucro das vísceras, deixar escoar e secar o invólucro e as vísceras descongeladas;"}, {"c": "dou-paragraph", "t": "6.11. Pesar a carcaça descongelada juntamente com as vísceras e seu invólucro, obtendo-se M₂ ; e"}, {"c": "dou-paragraph", "t": "6.12. Pesar o invólucro que continha as vísceras, obtendo-se M₃ ."}, {"c": "dou-paragraph", "t": "6.13. Caso as aves não contenham vísceras, M₂ será o peso da carcaça descongelada e M₃ será igual a zero."}, {"c": "dou-paragraph", "t": "7. Tempos de imersão de acordo com a massa da ave."}, {"c": "", "t": "Peso da ave mais suas vísceras (em gramas)"}, {"c": "", "t": "Tempo de imersão (em minutos)"}, {"c": "", "t": "Até 800"}, {"c": "", "t": "65"}, {"c": "", "t": "801 a 900"}, {"c": "", "t": "72"}, {"c": "", "t": "901 a 1.000"}, {"c": "", "t": "78"}, {"c": "", "t": "1.001 a 1.100"}, {"c": "", "t": "85"}, {"c": "", "t": "1.101 a 1.200"}, {"c": "", "t": "91"}, {"c": "", "t": "1.201 a 1.300"}, {"c": "", "t": "98"}, {"c": "", "t": "1.301 a 1.400"}, {"c": "", "t": "105"}, {"c": "dou-paragraph", "t": "Obs.: Acima de um mil e quatrocentos gramas (1.400g), aumentar o tempo de permanência no banho em sete minutos para cada cem gramas (100g) adicionais na massa da ave congelada."}, {"c": "dou-paragraph", "t": "8. Cálculo e expressão dos resultados:"}, {"c": "dou-paragraph", "t": "M 0 - M 1 - M 2"}, {"c": "dou-paragraph", "t": "% de líquido perdido por carcaça = --------------------- X 100"}, {"c": "dou-paragraph", "t": "M 0 - M 1 - M 3"}, {"c": "dou-paragraph", "t": "8.1. Reportar o valor do \"% de líquido perdido\" por carcaça e a média aritmética do \"% de líquido perdido\" com uma casa decimal."}, {"c": "dou-paragraph", "t": "ANEXO IV"}, {"c": "dou-paragraph", "t": "PARÂMETROS PARA AVALIAÇÃO DO TEOR TOTAL DE ÁGUA CONTIDA EM CARCAÇAS E CORTES DE AVES DA ESPÉCIE GALLUS GALLUS (FRANGO, GALO, GALINHA, GALETO)"}, {"c": "dou-paragraph", "t": "1. O teor total de água contida nas carcaças e nos cortes de frango, resfriados ou congelados será considerado conforme se atendidos os seguintes parâmetros máximos para a relação umidade/proteína:"}, {"c": "", "t": "PRODUTO"}, {"c": "", "t": "RELAÇÃO UMIDADE/PROTEÍNA"}, {"c": "", "t": "carcaças"}, {"c": "", "t": "4,41"}, {"c": "", "t": "coxa, com pele e osso"}, {"c": "", "t": "4,88"}, {"c": "", "t": "coxa com sobrecoxa, com pele e osso"}, {"c": "", "t": "4,72"}, {"c": "", "t": "peito, com pele e osso"}, {"c": "", "t": "4,09"}, {"c": "", "t": "peito sem pele e sem osso"}, {"c": "", "t": "4,02"}, {"c": "", "t": "sobrecoxa, com pele e osso"}, {"c": "", "t": "4,63"}, {"c": "dou-paragraph", "t": "2. As amostras coletadas para análises fiscais para a avaliação do teor total de água contida em carcaças e cortes de frango serão compostas por três unidades do produto obtidas do mesmo lote de produção."}, {"c": "dou-paragraph", "t": "3. O método oficial de ensaio para análise de amostras consta em manuais específicos do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "ANEXO V"}, {"c": "dou-paragraph", "t": "TABELA NUMÉRICA DE FUNCIONÁRIOS DE LINHAS DE INSPEÇÃO EM RELAÇÃO À VELOCIDADE DE ABATE NA LINHA DE EVISCERAÇÃO"}, {"c": "dou-paragraph", "t": "Tabela 1. Tipos de estabelecimentos conforme capacidade e velocidade de abate"}, {"c": "", "t": "Tipo 1 - Velocidade de até 1.800 aves/hora"}, {"c": "", "t": "Tipo 2 - Velocidade de 1.801 a 3.600 aves/hora"}, {"c": "", "t": "Tipo 3 - Velocidade de 3.601 a 5.400 aves/hora"}, {"c": "", "t": "Tipo 4 - Velocidade de 5.401 a 7.200 aves/hora"}, {"c": "", "t": "Tipo 5 - Velocidade de 7.201 a 9.000 aves/hora"}, {"c": "", "t": "Tipo 6 - Velocidade de 9.001 a 10.800 aves/hora"}, {"c": "", "t": "Tipo 7 - Velocidade de 10.801 a 11.808 aves/hora"}, {"c": "dou-paragraph", "t": "Tabela 2. Número de funcionários conforme tipo de estabelecimento"}, {"c": "", "t": "Linhas de inspeção"}, {"c": "", "t": "Número de funcionários"}, {"c": "", "t": "TIPO 1"}, {"c": "", "t": "TIPO 2"}, {"c": "", "t": "TIPO 3"}, {"c": "", "t": "TIPO 4"}, {"c": "", "t": "TIPO 5"}, {"c": "", "t": "TIPO 6"}, {"c": "", "t": "TIPO 7"}, {"c": "", "t": "Linha A Exame interno"}, {"c": "", "t": "1"}, {"c": "", "t": "2"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "6"}, {"c": "", "t": "7"}, {"c": "", "t": "Linha B Exame vísceras"}, {"c": "", "t": "1"}, {"c": "", "t": "2"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "6"}, {"c": "", "t": "7"}, {"c": "", "t": "Linha C Exame externo"}, {"c": "", "t": "1"}, {"c": "", "t": "2"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "6"}, {"c": "", "t": "7"}]});